function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function rows($s){try{return gdb_all($s)?:[];}catch(Throwable $e){return [];}} function one($s){try{return gdb_one($s)?:[];}catch(Throwable $e){return [];}}
$jobs=rows("SELECT * FROM goliath_browser_jobs ORDER BY id DESC LIMIT 50"); $hearts=rows("SELECT * FROM goliath_executive_heartbeat ORDER BY updated_at DESC LIMIT 20");
$stats=['queued'=>(int)(one("SELECT COUNT(*) c FROM goliath_browser_jobs WHERE status='queued'")['c']??0),'working'=>(int)(one("SELECT COUNT(*) c FROM goliath_browser_jobs WHERE status='working'")['c']??0),'complete'=>(int)(one("SELECT COUNT(*) c FROM goliath_browser_jobs WHERE status='complete'")['c']??0)];
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>GBI</title><style>body{margin:0;background:#030712;color:#fff;font-family:Arial}.wrap{max-width:1300px;margin:auto;padding:24px}.hero,.panel,.card{background:#07111f;border:1px solid #ffffff22;border-radius:20px;padding:16px;margin-bottom:14px}.hero h1{color:#d4af37}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px}.card b{font-size:28px}.muted{color:#94a3b8}.btn{background:#d4af37;color:#111;padding:9px 12px;border-radius:12px;text-decoration:none;font-weight:900}table{width:100%;border-collapse:collapse}td,th{border-bottom:1px solid #ffffff18;padding:8px;text-align:left}.bar{height:8px;background:#020617;border-radius:20px;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,#22c55e,#d4af37)}</style></head><body><div class="wrap"><section class="hero"><h1>Goliath Browser Intelligence</h1><p class="muted">Shared OpenClaw browser layer for the executive team.</p><a class="btn" target="_blank" href="/lead-engine/gbi-scout-seed.php?key=timetomakethedonuts&limit=20">Seed Scout Jobs</a></section><section class="grid"><div class="card"><b><?=h($stats['queued'])?></b><p>Queued</p></div><div class="card"><b><?=h($stats['working'])?></b><p>Working</p></div><div class="card"><b><?=h($stats['complete'])?></b><p>Complete</p></div></section><section class="panel"><h2>Heartbeats</h2><div class="grid"><?php foreach($hearts as $h): ?><div class="card"><h3><?=h(strtoupper($h['executive_key']))?></h3><p><?=h($h['status'])?> · <?=h($h['current_step'])?></p><div class="bar"><i style="width:<?=max(0,min(100,(int)$h['progress']))?>%"></i></div><p class="muted">Pages <?=h($h['pages_read'])?> · Phones <?=h($h['phones_found'])?> · Emails <?=h($h['emails_found'])?></p></div><?php endforeach; ?></div></section><section class="panel"><h2>Jobs</h2><table><tr><th>ID</th><th>Executive</th><th>Target</th><th>Status</th><th>Step</th></tr><?php foreach($jobs as $j): ?><tr><td><?=h($j['id'])?></td><td><?=h($j['executive_key'])?> / <?=h($j['job_type'])?></td><td><?=h($j['target_name'])?><br><span class="muted"><?=h($j['target_address'])?></span></td><td><?=h($j['status'])?> <?=h($j['progress'])?>%</td><td><?=h($j['current_step'])?></td></tr><?php endforeach; ?></table></section></div></body></html>